            for blob in connected_components(env.frame(), min_area=4)
            if blob.color not in (1, 2)
        ),
        flush=True,
    )
    after = {}
    for action, delta in action_deltas(env).items():
        child = env.clone()
        child.step(action)
        after[action] = {
            "pixels": delta["count"],
            "bbox": delta["bbox"],
            "state": compact(child),
        }
    print(
        "ACTION_DELTAS",
        after,
        flush=True,
